INSERT INTO course_pages (name, description, topic_id, raw_elements) VALUES
-- topic 12: Defining Functions  →  text + card + question
(
  'Defining Functions', 'def keyword, parameters, and docstrings.', 12,
  '[{"id":"el_fn01a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Defining Functions"}]},{"type":"paragraph","content":[{"type":"text","text":"A function groups reusable code under a name. Use the "},{"type":"text","marks":[{"type":"code"}],"text":"def"},{"type":"text","text":" keyword, choose a name, list parameters in parentheses, and add a colon. The indented body follows."}]},{"type":"paragraph","content":[{"type":"text","text":"Place a docstring immediately after the "},{"type":"text","marks":[{"type":"code"}],"text":"def"},{"type":"text","text":" line to document the function. Access it with "},{"type":"text","marks":[{"type":"code"}],"text":"help(fn)"},{"type":"text","text":" or "},{"type":"text","marks":[{"type":"code"}],"text":"fn.__doc__"},{"type":"text","text":"."}]}]}},{"id":"el_fn01b","type":"card","header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Naming convention"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Function names should be lowercase with underscores (snake_case). Use verbs: "},{"type":"text","marks":[{"type":"code"}],"text":"get_user"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"calculate_total"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"validate_input"},{"type":"text","text":". Avoid generic names like "},{"type":"text","marks":[{"type":"code"}],"text":"do_stuff"},{"type":"text","text":"."}]}]}}},{"id":"el_fn01c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where does the docstring go inside a function?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Immediately after the def line, before any code"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At the very end of the function body"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before the def line as a comment"}]}]}}],"answer":0}]'
),
-- topic 13: Return Values & Defaults  →  text + codeEditor + questionSlide
(
  'Return Values & Default Args', 'Returning data and using default argument values.', 13,
  '[{"id":"el_fn02a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Return Values and Default Arguments"}]},{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","marks":[{"type":"code"}],"text":"return"},{"type":"text","text":" to send a value back to the caller. A function with no return statement returns "},{"type":"text","marks":[{"type":"code"}],"text":"None"},{"type":"text","text":" implicitly. You can return multiple values as a tuple: "},{"type":"text","marks":[{"type":"code"}],"text":"return x, y"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Default argument values are evaluated "},{"type":"text","marks":[{"type":"bold"}],"text":"once"},{"type":"text","text":" when the function is defined. Never use mutable objects ("},{"type":"text","marks":[{"type":"code"}],"text":"[]"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"{}"},{"type":"text","text":") as defaults - they are shared across calls. Use "},{"type":"text","marks":[{"type":"code"}],"text":"None"},{"type":"text","text":" and assign inside the body instead."}]}]}},{"id":"el_fn02b","type":"codeEditor","language":"python","code":"def greet(name=\"World\"): return \"Hello, \" + name","maxLines":3},{"id":"el_fn02c","type":"questionSlide","questions":[{"id":"fn02q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does a function return if it has no return statement?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"None"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"0"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An empty string"}]}]}}],"answer":0},{"id":"fn02q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why should you never use [] as a default argument?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It is shared across all calls so mutations accumulate"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lists cannot be passed as function arguments"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python raises a TypeError for mutable defaults"}]}]}}],"answer":0}]}]'
),
-- topic 14: Closures & Scope  →  text + cardSlide + question
(
  'Closures & Scope', 'LEGB rule and closure mechanics.', 14,
  '[{"id":"el_fn03a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Scope and Closures"}]},{"type":"paragraph","content":[{"type":"text","text":"Python resolves names using the LEGB rule, checking four scopes in order. A "},{"type":"text","marks":[{"type":"bold"}],"text":"closure"},{"type":"text","text":" is an inner function that captures variables from its enclosing scope even after the outer function returns."}]}]}},{"id":"el_fn03b","type":"cardSlide","cards":[{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L - Local"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Variables defined inside the current function. Created fresh on each call and discarded when it returns. Python checks here first."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"E - Enclosing"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Variables in the local scope of any enclosing (outer) function when functions are nested. This is how closures capture values from their outer function."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"G - Global"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Variables defined at module top level. Use the "},{"type":"text","marks":[{"type":"code"}],"text":"global"},{"type":"text","text":" keyword inside a function if you need to write to this scope."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"B - Built-in"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python built-in names: "},{"type":"text","marks":[{"type":"code"}],"text":"len"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"range"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"print"},{"type":"text","text":". Checked last. Never shadow these with your own variables."}]}]}}}]},{"id":"el_fn03c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In the LEGB rule, which scope is checked first?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Local"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Global"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Built-in"}]}]}}],"answer":0}]'
),
-- topic 15: React Router Basics  →  text + cardSlide + questionSlide
(
  'React Router Basics', 'Routes, Links, and URL parameters.', 15,
  '[{"id":"el_rr01a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"React Router"}]},{"type":"paragraph","content":[{"type":"text","text":"React Router maps URL paths to components without full page reloads. Wrap the app in "},{"type":"text","marks":[{"type":"code"}],"text":"<BrowserRouter>"},{"type":"text","text":" and declare routes with "},{"type":"text","marks":[{"type":"code"}],"text":"<Routes>"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"<Route path=\"/\" element={<Home />} />"},{"type":"text","text":"."}]}]}},{"id":"el_rr01b","type":"cardSlide","cards":[{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"<Link>"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Renders an anchor that navigates without a full reload. Use instead of plain "},{"type":"text","marks":[{"type":"code"}],"text":"<a href>"},{"type":"text","text":" for all internal navigation."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"<NavLink>"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Like "},{"type":"text","marks":[{"type":"code"}],"text":"<Link>"},{"type":"text","text":" but automatically adds an "},{"type":"text","marks":[{"type":"code"}],"text":"active"},{"type":"text","text":" class when the current URL matches its "},{"type":"text","marks":[{"type":"code"}],"text":"to"},{"type":"text","text":" prop. Useful for navigation menus."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"useParams"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reads dynamic URL segments. If your route is "},{"type":"text","marks":[{"type":"code"}],"text":"/user/:id"},{"type":"text","text":", then "},{"type":"text","marks":[{"type":"code"}],"text":"const { id } = useParams()"},{"type":"text","text":" gives you the value from the URL."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"useNavigate"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returns a function for programmatic navigation: "},{"type":"text","marks":[{"type":"code"}],"text":"navigate(\"/home\")"},{"type":"text","text":" or "},{"type":"text","marks":[{"type":"code"}],"text":"navigate(-1)"},{"type":"text","text":" to go back. Use after form submissions or auth checks."}]}]}}}]},{"id":"el_rr01c","type":"questionSlide","questions":[{"id":"rr01q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which hook reads a dynamic URL segment like /user/:id?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"useParams"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"useLocation"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"useNavigate"}]}]}}],"answer":0},{"id":"rr01q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What advantage does <NavLink> have over <Link>?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It adds an active class when the URL matches"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It loads the target page faster"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It works with external URLs"}]}]}}],"answer":0}]}]'
),
-- topic 16: Controlled Forms  →  text + card + question
(
  'Controlled Forms', 'Binding input values to state.', 16,
  '[{"id":"el_rr02a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Controlled Forms"}]},{"type":"paragraph","content":[{"type":"text","text":"In a controlled form, React state is the single source of truth for each input. Every input needs a "},{"type":"text","marks":[{"type":"code"}],"text":"value"},{"type":"text","text":" prop bound to state and an "},{"type":"text","marks":[{"type":"code"}],"text":"onChange"},{"type":"text","text":" handler that calls the setter."}]},{"type":"paragraph","content":[{"type":"text","text":"This enables keystroke-level validation, disabling submit until the form is valid, and transforming input before storage. Contrast with "},{"type":"text","marks":[{"type":"bold"}],"text":"uncontrolled forms"},{"type":"text","text":" (read values via a ref on submit) which are simpler but harder to validate incrementally."}]}]}},{"id":"el_rr02b","type":"card","header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Watch out"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An input with "},{"type":"text","marks":[{"type":"code"}],"text":"value"},{"type":"text","text":" but no "},{"type":"text","marks":[{"type":"code"}],"text":"onChange"},{"type":"text","text":" becomes read-only and React will warn you in the console. If you want an initial value without controlling it, use "},{"type":"text","marks":[{"type":"code"}],"text":"defaultValue"},{"type":"text","text":" instead."}]}]}}},{"id":"el_rr02c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a controlled input, what must you always provide alongside the value prop?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An onChange handler"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A defaultValue prop"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ref attribute"}]}]}}],"answer":0}]'
),
-- topic 17: Two Pointers  →  text + cardSlide + questionSlide
(
  'Two Pointers', 'Solving array problems with two moving indices.', 17,
  '[{"id":"el_dsa01a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Two Pointers"}]},{"type":"paragraph","content":[{"type":"text","text":"Two indices placed into a sequence and moved strategically can turn many O(n^2) brute-force solutions into O(n). There are three main patterns - each suits a different problem shape."}]}]}},{"id":"el_dsa01b","type":"cardSlide","cards":[{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Opposite ends"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Start "},{"type":"text","marks":[{"type":"code"}],"text":"left=0"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"right=n-1"},{"type":"text","text":" and converge inward. Classic uses: two-sum on a sorted array, valid palindrome, container with most water."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Slow and fast"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One pointer advances every step; the other every two. Used for Floyd cycle detection, finding the middle of a linked list, and finding the start of a cycle."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Partition"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One pointer marks a boundary; the other scans forward swapping qualifying elements. Used for: remove duplicates in-place, Dutch national flag, move zeros to end."}]}]}}}]},{"id":"el_dsa01c","type":"questionSlide","questions":[{"id":"dsa01q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What time complexity does two pointers typically achieve over a brute-force nested loop?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O(n^2) reduced to O(n)"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O(n) reduced to O(log n)"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O(n log n) reduced to O(n)"}]}]}}],"answer":0},{"id":"dsa01q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which two-pointer pattern detects a cycle in a linked list?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Slow and fast pointers"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Opposite ends"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Partition"}]}]}}],"answer":0}]}]'
),
-- topic 18: Sliding Window
(
  'Sliding Window', 'Fixed and variable-size window techniques.', 18,
  '[{"id":"el_dsa02a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Sliding Window"}]},{"type":"paragraph","content":[{"type":"text","text":"A sliding window maintains a contiguous subarray (or substring) and slides across the data by advancing one or both ends. It avoids recomputing the entire window from scratch each step."}]},{"type":"paragraph","content":[{"type":"text","text":"Use a "},{"type":"text","marks":[{"type":"bold"}],"text":"fixed-size window"},{"type":"text","text":" when the problem specifies a size k: add the new element, subtract the element leaving the window. Use a "},{"type":"text","marks":[{"type":"bold"}],"text":"variable-size window"},{"type":"text","text":" (expand right, shrink left) when the constraint is on the window's content (e.g. at most k distinct characters)."}]}]}},{"id":"el_dsa02b","type":"table","cells":[["Type","Pointer movement","Example problem"],["Fixed window","both move together","Max sum subarray of size k"],["Variable window","right expands, left shrinks","Longest substring without repeats"],["Prefix sum","precompute then query","Subarray sum equals target"]]},{"id":"el_dsa02c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a variable sliding window, when do you advance the left pointer?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the window violates the constraint"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After every iteration regardless"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Only when the right pointer reaches the end"}]}]}}],"answer":0}]'
),
-- topic 19: Binary Trees & BFS  →  text + card + question
(
  'Binary Trees & BFS', 'Level-order traversal with a queue.', 19,
  '[{"id":"el_dsa03a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Binary Trees and BFS"}]},{"type":"paragraph","content":[{"type":"text","text":"A binary tree is a recursive structure where each node has at most two children: left and right. Key properties: "},{"type":"text","marks":[{"type":"bold"}],"text":"height"},{"type":"text","text":" (longest root-to-leaf path) and "},{"type":"text","marks":[{"type":"bold"}],"text":"depth"},{"type":"text","text":" (distance from root)."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Breadth-First Search"}]},{"type":"paragraph","content":[{"type":"text","text":"BFS visits nodes level by level using a queue. Enqueue the root; dequeue a node, process it, enqueue its children. Repeat. This gives level-order traversal and finds the shortest path in unweighted graphs."}]}]}},{"id":"el_dsa03b","type":"card","header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"BST property"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a Binary Search Tree every value in the left subtree is less than the node, and every value in the right subtree is greater. This enables O(log n) search, insert, and delete on a balanced tree."}]}]}}},{"id":"el_dsa03c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What data structure does BFS use to process nodes level by level?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Queue (FIFO)"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stack (LIFO)"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Min-heap (priority queue)"}]}]}}],"answer":0}]'
),
-- topic 20: DFS & Graph Traversal  →  text + table + questionSlide
(
  'DFS & Graph Traversal', 'Recursive and iterative depth-first search.', 20,
  '[{"id":"el_dsa04a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Depth-First Search"}]},{"type":"paragraph","content":[{"type":"text","text":"DFS explores as deep as possible along one branch before backtracking. On trees: pre-order (root first), in-order (left, root, right), or post-order (children first). On graphs, maintain a "},{"type":"text","marks":[{"type":"code"}],"text":"visited"},{"type":"text","text":" set to avoid infinite loops from cycles."}]}]}},{"id":"el_dsa04b","type":"table","cells":[["Property","BFS","DFS"],["Data structure","Queue","Stack / recursion"],["Memory usage","O(width)","O(height)"],["Shortest path (unweighted)","Yes","No"],["Cycle detection","Yes","Yes"],["Topological sort","No","Yes (post-order)"]]},{"id":"el_dsa04c","type":"questionSlide","questions":[{"id":"dsa04q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must you track visited nodes when doing DFS on a graph?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To avoid infinite loops from cycles"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To ensure alphabetical processing order"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To reduce memory usage"}]}]}}],"answer":0},{"id":"dsa04q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which traversal order is used for topological sorting?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Post-order DFS"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pre-order DFS"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Level-order BFS"}]}]}}],"answer":0}]}]'
),
-- topic 21: Linear Regression  →  text + codeEditor + questionSlide
(
  'Linear Regression', 'Fitting a line to minimise squared error.', 21,
  '[{"id":"el_ml01a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Linear Regression"}]},{"type":"paragraph","content":[{"type":"text","text":"Linear regression fits "},{"type":"text","marks":[{"type":"code"}],"text":"y = w*x + b"},{"type":"text","text":" to minimise "},{"type":"text","marks":[{"type":"bold"}],"text":"Mean Squared Error (MSE)"},{"type":"text","text":" - the average squared gap between predictions and true values. Weights are found analytically (normal equation) or with gradient descent."}]},{"type":"paragraph","content":[{"type":"text","text":"The scikit-learn API: create a model, call "},{"type":"text","marks":[{"type":"code"}],"text":"fit(X, y)"},{"type":"text","text":" to train, "},{"type":"text","marks":[{"type":"code"}],"text":"predict(X)"},{"type":"text","text":" to infer, and "},{"type":"text","marks":[{"type":"code"}],"text":"score(X, y)"},{"type":"text","text":" to get R^2."}]}]}},{"id":"el_ml01b","type":"codeEditor","language":"python","code":"from sklearn.linear_model import LinearRegression; m = LinearRegression(); m.fit(X_train, y_train); print(m.score(X_test, y_test))","maxLines":4},{"id":"el_ml01c","type":"questionSlide","questions":[{"id":"ml01q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What loss does linear regression minimise?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mean Squared Error (MSE)"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cross-entropy loss"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hinge loss"}]}]}}],"answer":0},{"id":"ml01q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does gradient descent do during training?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iteratively updates weights to reduce the loss"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Splits data into train and test sets"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Normalises feature values to zero mean"}]}]}}],"answer":0}]}]'
),
-- topic 22: Decision Trees  →  text + cardSlide + question
(
  'Decision Trees', 'Splitting data by information gain.', 22,
  '[{"id":"el_ml02a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Decision Trees"}]},{"type":"paragraph","content":[{"type":"text","text":"A decision tree recursively splits data by choosing the feature and threshold that best separates the classes. Split quality is measured by "},{"type":"text","marks":[{"type":"bold"}],"text":"information gain"},{"type":"text","text":" (entropy reduction) or "},{"type":"text","marks":[{"type":"bold"}],"text":"Gini impurity"},{"type":"text","text":". A pure node (Gini = 0) contains samples from only one class."}]}]}},{"id":"el_ml02b","type":"cardSlide","cards":[{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pros"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Highly interpretable - the tree is readable if-else rules"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No feature scaling required"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Handles categorical and numerical features"}]}]}]}}]}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cons"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prone to overfitting without max-depth or min-samples limits"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unstable - small data changes produce very different trees"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Biased toward high-cardinality features"}]}]}]}}]}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ensembles"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Random Forest trains many trees on random data and feature subsets and averages their predictions. XGBoost / LightGBM add trees sequentially to fix prior errors (boosting). Both greatly outperform single trees."}]}]}}}]},{"id":"el_ml02c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does a Gini impurity of 0 mean for a node?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All samples belong to the same class"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The node has equal samples of every class"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No more splits are possible"}]}]}}],"answer":0}]'
),
-- topic 23: K-Means  →  text + cardSlide + questionSlide
(
  'K-Means Clustering', 'Partitioning data into k clusters.', 23,
  '[{"id":"el_ml03a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"K-Means Clustering"}]},{"type":"paragraph","content":[{"type":"text","text":"K-means partitions n points into k clusters by minimising within-cluster squared distances to the centroid. It is "},{"type":"text","marks":[{"type":"bold"}],"text":"unsupervised"},{"type":"text","text":" - no labels needed. Convergence is guaranteed but the result depends on initialisation."}]}]}},{"id":"el_ml03b","type":"cardSlide","cards":[{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"1. Initialise"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose k starting centroids randomly or using "},{"type":"text","marks":[{"type":"bold"}],"text":"k-means++"},{"type":"text","text":" (spread them out) to reduce the chance of a poor local minimum."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"2. Assign"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Assign each data point to the nearest centroid by Euclidean distance. Points assigned to the same centroid form one cluster."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"3. Update"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recompute each centroid as the mean of all points in its cluster. The centroid moves to the geometric centre."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"4. Repeat"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeat assign and update until no point changes cluster. Use the "},{"type":"text","marks":[{"type":"bold"}],"text":"elbow method"},{"type":"text","text":" (plot inertia vs k) to choose the right k."}]}]}}}]},{"id":"el_ml03c","type":"questionSlide","questions":[{"id":"ml03q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does the elbow method help you choose?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The optimal number of clusters k"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The learning rate"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Whether the data is linearly separable"}]}]}}],"answer":0},{"id":"ml03q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is K-means supervised or unsupervised?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unsupervised - no labels required"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Supervised - requires labelled data"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Semi-supervised - uses a few labels"}]}]}}],"answer":0}]}]'
),
-- topic 24: PCA  →  text + card + question
(
  'Principal Component Analysis', 'Reducing dimensions while preserving variance.', 24,
  '[{"id":"el_ml04a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"PCA - Principal Component Analysis"}]},{"type":"paragraph","content":[{"type":"text","text":"PCA finds the directions of maximum variance in high-dimensional data (principal components) and projects onto a lower-dimensional subspace. Each component is an eigenvector of the covariance matrix; its eigenvalue tells you how much variance it captures."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Steps"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Standardise features to zero mean and unit variance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compute the covariance matrix."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find eigenvectors and eigenvalues."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Project data onto the top k eigenvectors."}]}]}]}]}},{"id":"el_ml04b","type":"card","header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"When to use PCA"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use when features are highly correlated, when you want 2D/3D visualisation of high-dimensional data, or to speed up training. Avoid it when interpretability matters - transformed features have no direct meaning."}]}]}}},{"id":"el_ml04c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does the eigenvalue of a principal component represent?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The amount of variance explained by that component"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The number of data points projected onto it"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The prediction error after projection"}]}]}}],"answer":0}]'
),
-- topic 25: Load Balancers  →  text + cardSlide + questionSlide
(
  'Load Balancers', 'Distributing traffic across servers.', 25,
  '[{"id":"el_sd01a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Load Balancers"}]},{"type":"paragraph","content":[{"type":"text","text":"A load balancer sits in front of a server pool and distributes incoming requests so no single server becomes a bottleneck. It also hides server failures from clients. L4 load balancers route at the TCP level; L7 load balancers route based on HTTP content (URL, headers, cookies)."}]}]}},{"id":"el_sd01b","type":"cardSlide","cards":[{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Round Robin"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each request goes to the next server in rotation. Simple and even distribution, but ignores current server load. A weighted variant gives higher-capacity servers a larger share."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Least Connections"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Routes to the server with fewest active connections. Better than round-robin when requests have variable processing time."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IP Hash"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hashes the client IP to select a server. The same client always hits the same server (sticky sessions) - useful when server-side session state is not shared."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L4 vs L7"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L4 (transport) routes on IP/port - fast and simple. L7 (application) routes on URL path, headers, cookies - slower but enables advanced routing like A/B testing or service meshes."}]}]}}}]},{"id":"el_sd01c","type":"questionSlide","questions":[{"id":"sd01q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which algorithm ensures the same client always reaches the same server?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IP hash"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Round robin"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Least connections"}]}]}}],"answer":0},{"id":"sd01q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At which OSI layer does an L7 load balancer operate?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Application layer (HTTP)"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Transport layer (TCP)"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Network layer (IP)"}]}]}}],"answer":0}]}]'
),
-- topic 26: Horizontal vs Vertical Scaling
(
  'Horizontal vs Vertical Scaling', 'Scale-out versus scale-up trade-offs.', 26,
  '[{"id":"el_sd02a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Horizontal vs Vertical Scaling"}]},{"type":"paragraph","content":[{"type":"text","text":"When a system needs more capacity you can scale "},{"type":"text","marks":[{"type":"bold"}],"text":"vertically"},{"type":"text","text":" (add CPU/RAM to existing machines) or "},{"type":"text","marks":[{"type":"bold"}],"text":"horizontally"},{"type":"text","text":" (add more machines). Most modern web services prefer horizontal scaling because it avoids a single point of failure and has no hard upper limit."}]}]}},{"id":"el_sd02b","type":"table","cells":[["Dimension","Vertical (scale up)","Horizontal (scale out)"],["Cost","Expensive hardware","Commodity servers"],["Limit","Hardware ceiling","Effectively unbounded"],["Downtime","Often required","Can add nodes live"],["Complexity","Simple, single machine","Needs distributed coordination"],["Failure","Single point of failure","Redundant nodes"]]},{"id":"el_sd02c","type":"question","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the main advantage of horizontal scaling over vertical scaling?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No hard upper limit and eliminates single point of failure"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It requires less application code changes"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It is always cheaper per unit of compute"}]}]}}],"answer":0}]'
),
-- topic 27: Caching Strategies  →  text + cardSlide + questionSlide
(
  'Caching Strategies', 'Cache-aside, write-through, and eviction policies.', 27,
  '[{"id":"el_sd03a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Caching Strategies"}]},{"type":"paragraph","content":[{"type":"text","text":"A cache stores frequently accessed data in memory to cut latency and database load. Two key concerns: keeping the cache consistent with the source of truth, and deciding what to evict when capacity is full."}]}]}},{"id":"el_sd03b","type":"cardSlide","cards":[{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cache-aside"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"App checks cache first. On a miss, it reads from DB and writes the result to cache. On writes, it updates DB and invalidates the cache entry. Simple and resilient to cache failure."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write-through"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every write goes to cache and DB simultaneously. Cache is always consistent but writes are slower. Good for read-heavy workloads where stale data is unacceptable."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write-back"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Writes go to cache only; DB is updated asynchronously. Fast writes but risk of data loss if the cache crashes before flushing. Suitable where brief inconsistency is acceptable."}]}]}}},{"header":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Eviction policies"}]}]}},"content":{"content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"LRU"},{"type":"text","text":" - evict the least recently accessed item"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"LFU"},{"type":"text","text":" - evict the item accessed fewest times overall"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"TTL"},{"type":"text","text":" - evict items after a fixed time-to-live regardless of access"}]}]}]}}]}}}]},{"id":"el_sd03c","type":"questionSlide","questions":[{"id":"sd03q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In cache-aside, who populates the cache on a miss?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The application"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The database"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cache itself"}]}]}}],"answer":0},{"id":"sd03q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which eviction policy removes the item not accessed for the longest time?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LRU"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LFU"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"TTL"}]}]}}],"answer":0}]}]'
),
-- topic 28: Database Sharding  →  text + table + questionSlide
(
  'Database Sharding', 'Partitioning data across multiple database nodes.', 28,
  '[{"id":"el_sd04a","type":"text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Database Sharding"}]},{"type":"paragraph","content":[{"type":"text","text":"Sharding horizontally partitions a table across multiple database instances (shards). Each shard holds a subset of rows, distributing both read and write load. Cross-shard joins are expensive - minimise them through denormalisation or careful shard key choice."}]}]}},{"id":"el_sd04b","type":"table","cells":[["Strategy","How it works","Hot spot risk","Re-shard cost"],["Range-based","Assign ID ranges to shards","High for recent data","Low"],["Hash-based","shard = hash(key) % n","Low - even spread","High - remaps all keys"],["Directory-based","Lookup table maps key to shard","Low","Medium"]]},{"id":"el_sd04c","type":"questionSlide","questions":[{"id":"sd04q1","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can range-based sharding create hot spots?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recent writes cluster on the highest-range shard"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash collisions send all traffic to one shard"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The directory lookup becomes a bottleneck"}]}]}}],"answer":0},{"id":"sd04q2","question":{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is re-sharding expensive with hash-based sharding?"}]}]}},"options":[{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Changing n remaps almost all keys to different shards"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The lookup table must be rebuilt from scratch"}]}]}},{"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hashing is too slow for large datasets"}]}]}}],"answer":0}]}]'
);

